SELECT id, supplier_name, country, city, COUNT(rating) OVER (PARTITION BY country ORDER BY rating, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_count_rating, MIN(rating) OVER (PARTITION BY country ORDER BY rating, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_min_rating, AVG(rating) OVER (PARTITION BY country ORDER BY rating, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_avg_rating FROM suppliers WHERE city IN ('Bangkok', 'Chiang Mai', 'Berlin');
